package edu.kle.permits;

import java.time.*;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PermitService {
 private final PermitRecords permits;private final ApplicationVersions versions;private final Assignments assignments;private final Reviews reviews;private final Corrections corrections;private final Payments payments;private final Inspections inspections;private final WorkflowHistories history;private final Users users;private final Clock clock;
 public PermitService(PermitRecords p,ApplicationVersions v,Assignments a,Reviews r,Corrections c,Payments pay,Inspections i,WorkflowHistories h,Users u,Clock clock){permits=p;versions=v;assignments=a;reviews=r;corrections=c;payments=pay;inspections=i;history=h;users=u;this.clock=clock;}

 @Transactional public PermitDtos.ApplicationView create(PermitDtos.ApplicationInput d,AppUser actor){requireRole(actor,Role.APPLICANT);Instant now=clock.instant();PermitRecord p=permits.save(new PermitRecord(actor.id,d,now));p.permitNumber="PW-"+now.atZone(ZoneOffset.UTC).getYear()+"-"+String.format("%06d",p.id);log(p,null,"DRAFT_CREATED",null,actor);return view(p,actor);}
 @Transactional public PermitDtos.ApplicationView edit(Long id,PermitDtos.ApplicationInput d,AppUser actor){PermitRecord p=lockedAccessible(id,actor);own(p,actor);if(p.status!=PermitStatus.DRAFT&&p.status!=PermitStatus.CORRECTION_REQUIRED)conflict("Applications can be edited only while draft or while corrections are required.");p.apply(d);p.updatedAt=clock.instant();log(p,p.status,"APPLICATION_UPDATED",null,actor);return view(p,actor);}
 @Transactional public PermitDtos.ApplicationView submit(Long id,AppUser actor){PermitRecord p=lockedAccessible(id,actor);own(p,actor);if(p.status!=PermitStatus.DRAFT)conflict("Only a draft application can be submitted.");transition(p,PermitStatus.SUBMITTED,"APPLICATION_SUBMITTED",null,actor);versions.save(new ApplicationVersion(p,clock.instant()));return view(p,actor);}
 @Transactional public PermitDtos.ApplicationView resubmit(Long id,PermitDtos.Resubmit d,AppUser actor){PermitRecord p=lockedAccessible(id,actor);own(p,actor);if(p.status!=PermitStatus.CORRECTION_REQUIRED)conflict("This application is not awaiting corrections.");List<CorrectionRequest> open=corrections.findByApplicationIdAndResolvedFalse(id);if(open.isEmpty())conflict("No unresolved correction request exists.");Instant now=clock.instant();open.forEach(c->{c.resolved=true;c.applicantResponse=d.response().trim();c.resubmittedAt=now;});p.reviewRound++;transition(p,PermitStatus.RESUBMITTED,"APPLICATION_RESUBMITTED",d.response().trim(),actor);versions.save(new ApplicationVersion(p,now));return view(p,actor);}

 @Transactional public PermitDtos.ApplicationView verifyDocuments(Long id,PermitDtos.DocumentDecision d,AppUser actor){requireRole(actor,Role.DEPARTMENT_OFFICER);PermitRecord p=lock(id);if(p.status!=PermitStatus.SUBMITTED&&p.status!=PermitStatus.RESUBMITTED)conflict("Document verification requires a submitted application.");if(d.complete()){transition(p,PermitStatus.DOCUMENT_VERIFICATION,"DOCUMENTS_VERIFIED",clean(d.remarks()),actor);}else{String note=required(d.remarks(),"Remarks are required when documents are incomplete.");corrections.save(new CorrectionRequest(p,actor,note,clock.instant()));transition(p,PermitStatus.CORRECTION_REQUIRED,"DOCUMENTS_INCOMPLETE",note,actor);}return view(p,actor);}
 @Transactional public PermitDtos.ApplicationView assign(Long id,PermitDtos.AssignmentInput d,AppUser actor){requireRole(actor,Role.DEPARTMENT_OFFICER);PermitRecord p=lock(id);Role required=Role.valueOf(d.type().name());AppUser assignee=users.findById(d.assigneeId()).filter(u->u.enabled&&u.role==required).orElseThrow(()->bad("The selected user is not an enabled "+required.name().replace('_',' ')+"."));boolean inspector=d.type()==AssignmentType.BUILDING_INSPECTOR;if(inspector){if(!Set.of(PermitStatus.APPROVED,PermitStatus.PAYMENT_PENDING,PermitStatus.PERMIT_ISSUED,PermitStatus.INSPECTION_FAILED,PermitStatus.INSPECTION_PASSED).contains(p.status))conflict("An inspector can be assigned only after approval.");}else if(!Set.of(PermitStatus.DOCUMENT_VERIFICATION,PermitStatus.ASSIGNED,PermitStatus.RESUBMITTED).contains(p.status))conflict("Review officers can be assigned only after document verification.");assignments.deactivate(id,d.type());assignments.save(new ApplicationAssignment(id,d.type(),assignee.id,actor.id,clock.instant()));PermitStatus old=p.status;if(!inspector){p.status=PermitStatus.ASSIGNED;if(active(id,AssignmentType.PERMIT_REVIEWER).isPresent()&&active(id,AssignmentType.ZONING_OFFICER).isPresent())p.status=PermitStatus.TECHNICAL_REVIEW;}p.updatedAt=clock.instant();log(p,old,"OFFICER_ASSIGNED",d.type()+": "+assignee.email,actor);return view(p,actor);}
 @Transactional public PermitDtos.ApplicationView review(Long id,ReviewType type,PermitDtos.ReviewInput d,AppUser actor){Role role=type==ReviewType.TECHNICAL?Role.PERMIT_REVIEWER:Role.ZONING_OFFICER;requireRole(actor,role);PermitRecord p=lock(id);AssignmentType at=type==ReviewType.TECHNICAL?AssignmentType.PERMIT_REVIEWER:AssignmentType.ZONING_OFFICER;assigned(id,at,actor);PermitStatus expected=type==ReviewType.TECHNICAL?PermitStatus.TECHNICAL_REVIEW:PermitStatus.ZONING_REVIEW;if(type==ReviewType.TECHNICAL&&p.status==PermitStatus.RESUBMITTED)expected=PermitStatus.RESUBMITTED;if(p.status!=expected)conflict(type+" review is not available in status "+p.status+".");String note=clean(d.remarks());if(d.recommendation()==ReviewRecommendation.CORRECTION_REQUIRED)note=required(note,"Correction remarks are required.");reviews.save(new ApplicationReview(p,type,actor.id,d.recommendation(),note,clock.instant()));if(d.recommendation()==ReviewRecommendation.CORRECTION_REQUIRED){corrections.save(new CorrectionRequest(p,actor,note,clock.instant()));transition(p,PermitStatus.CORRECTION_REQUIRED,type+"_CORRECTION_REQUESTED",note,actor);}else transition(p,type==ReviewType.TECHNICAL?PermitStatus.ZONING_REVIEW:PermitStatus.PENDING_FINAL_DECISION,type+"_REVIEW_APPROVED",note,actor);return view(p,actor);}
 @Transactional public PermitDtos.ApplicationView decide(Long id,PermitDtos.DecisionInput d,AppUser actor){requireRole(actor,Role.SENIOR_DEPARTMENT_OFFICER);PermitRecord p=lock(id);if(p.status!=PermitStatus.PENDING_FINAL_DECISION)conflict("A final decision requires completed technical and zoning reviews.");String decision=d.decision().trim().toUpperCase(Locale.ROOT),note=clean(d.remarks());switch(decision){case "APPROVE"->transition(p,PermitStatus.APPROVED,"APPLICATION_APPROVED",note,actor);case "REJECT"->{note=required(note,"A rejection reason is required.");transition(p,PermitStatus.REJECTED,"APPLICATION_REJECTED",note,actor);}case "CORRECTION"->{note=required(note,"Correction remarks are required.");corrections.save(new CorrectionRequest(p,actor,note,clock.instant()));transition(p,PermitStatus.CORRECTION_REQUIRED,"FINAL_CORRECTION_REQUESTED",note,actor);}default->throw bad("Decision must be APPROVE, REJECT or CORRECTION.");}return view(p,actor);}
 @Transactional public PermitDtos.ApplicationView payment(Long id,PermitDtos.PaymentInput d,AppUser actor){requireRole(actor,Role.FINANCE_OFFICER);PermitRecord p=lock(id);if(!Set.of(PermitStatus.APPROVED,PermitStatus.PAYMENT_PENDING).contains(p.status))conflict("Payment can be recorded only for an approved application awaiting payment.");String ref=clean(d.paymentReference());if(d.status()==PaymentStatus.PAID)ref=required(ref,"A simulated payment reference is required when marking paid.");PaymentRecord pay=payments.findByApplicationId(id).orElseGet(PaymentRecord::new);pay.applicationId=id;pay.feeAmount=d.feeAmount();pay.paymentStatus=d.status();pay.paymentReference=ref;pay.recordedBy=actor.id;pay.recordedAt=clock.instant();payments.save(pay);transition(p,d.status()==PaymentStatus.PAID?PermitStatus.PERMIT_ISSUED:PermitStatus.PAYMENT_PENDING,d.status()==PaymentStatus.PAID?"PAYMENT_RECORDED_PERMIT_ISSUED":"FEE_RECORDED",ref,actor);return view(p,actor);}
 @Transactional public PermitDtos.ApplicationView schedule(Long id,PermitDtos.InspectionInput d,AppUser actor){requireRole(actor,Role.BUILDING_INSPECTOR);PermitRecord p=lock(id);assigned(id,AssignmentType.BUILDING_INSPECTOR,actor);if(!Set.of(PermitStatus.PERMIT_ISSUED,PermitStatus.INSPECTION_FAILED,PermitStatus.INSPECTION_PASSED).contains(p.status))conflict("An inspection can be scheduled only for an issued permit or after an inspection result.");InspectionRecord i=new InspectionRecord();i.applicationId=id;i.inspectorId=actor.id;i.inspectionType=d.inspectionType().trim();i.scheduledDate=d.scheduledDate();i.result=InspectionResult.SCHEDULED;i.finalInspection=d.finalInspection();i.createdAt=i.updatedAt=clock.instant();inspections.save(i);transition(p,PermitStatus.INSPECTION_SCHEDULED,"INSPECTION_SCHEDULED",i.inspectionType,actor);return view(p,actor);}
 @Transactional public PermitDtos.ApplicationView recordInspection(Long id,Long inspectionId,PermitDtos.InspectionResultInput d,AppUser actor){requireRole(actor,Role.BUILDING_INSPECTOR);PermitRecord p=lock(id);assigned(id,AssignmentType.BUILDING_INSPECTOR,actor);InspectionRecord i=inspections.findByIdAndInspectorId(inspectionId,actor.id).filter(x->x.applicationId.equals(id)).orElseThrow(()->notFound("Inspection not found."));if(i.result!=InspectionResult.SCHEDULED||p.status!=PermitStatus.INSPECTION_SCHEDULED)conflict("Only a scheduled inspection can receive a result.");if(d.result()==InspectionResult.SCHEDULED)throw bad("Result must be PASSED or FAILED.");i.conductedDate=d.conductedDate();i.observations=d.observations().trim();i.result=d.result();i.updatedAt=clock.instant();transition(p,d.result()==InspectionResult.PASSED?PermitStatus.INSPECTION_PASSED:PermitStatus.INSPECTION_FAILED,"INSPECTION_"+d.result(),i.observations,actor);return view(p,actor);}
 @Transactional public PermitDtos.ApplicationView close(Long id,AppUser actor){requireRole(actor,Role.BUILDING_INSPECTOR);PermitRecord p=lock(id);assigned(id,AssignmentType.BUILDING_INSPECTOR,actor);boolean finalPass=inspections.findByApplicationIdOrderByCreatedAt(id).stream().anyMatch(i->i.finalInspection&&i.result==InspectionResult.PASSED);if(p.status!=PermitStatus.INSPECTION_PASSED||!finalPass)conflict("The project can close only after a successful final inspection.");transition(p,PermitStatus.PROJECT_CLOSED,"PROJECT_CLOSED",null,actor);return view(p,actor);}

 @Transactional(readOnly=true) public PermitDtos.Dashboard dashboard(AppUser actor){List<PermitRecord> list=accessible(actor);Map<String,Long> counts=list.stream().collect(Collectors.groupingBy(p->p.status.name(),TreeMap::new,Collectors.counting()));return new PermitDtos.Dashboard(counts,list.stream().map(this::summary).toList());}
 @Transactional(readOnly=true) public PermitDtos.ApplicationView get(Long id,AppUser actor){PermitRecord p=permits.findById(id).orElseThrow(()->notFound("Application not found."));if(!canAccess(p,actor))throw notFound("Application not found.");return view(p,actor);}
 @Transactional(readOnly=true) public List<Dtos.UserView> officers(Role role,AppUser actor){if(actor.role!=Role.DEPARTMENT_OFFICER&&actor.role!=Role.ADMIN)throw forbidden();if(!Set.of(Role.PERMIT_REVIEWER,Role.ZONING_OFFICER,Role.BUILDING_INSPECTOR).contains(role))throw bad("Role is not assignable.");return users.findByRoleAndEnabledTrueOrderByFullName(role).stream().map(Dtos.UserView::of).toList();}

 private List<PermitRecord> accessible(AppUser actor){List<PermitRecord> all=actor.role==Role.APPLICANT?permits.findByApplicantIdOrderByUpdatedAtDesc(actor.id):permits.findAllByOrderByUpdatedAtDesc();return all.stream().filter(p->canAccess(p,actor)).toList();}
 private boolean canAccess(PermitRecord p,AppUser actor){return switch(actor.role){
  case APPLICANT->p.applicantId.equals(actor.id);
  case PERMIT_REVIEWER->active(p.id,AssignmentType.PERMIT_REVIEWER).map(a->a.assigneeId.equals(actor.id)).orElse(false);
  case ZONING_OFFICER->active(p.id,AssignmentType.ZONING_OFFICER).map(a->a.assigneeId.equals(actor.id)).orElse(false);
  case BUILDING_INSPECTOR->active(p.id,AssignmentType.BUILDING_INSPECTOR).map(a->a.assigneeId.equals(actor.id)).orElse(false);
  case FINANCE_OFFICER->Set.of(PermitStatus.APPROVED,PermitStatus.PAYMENT_PENDING,PermitStatus.PERMIT_ISSUED,PermitStatus.INSPECTION_SCHEDULED,PermitStatus.INSPECTION_FAILED,PermitStatus.INSPECTION_PASSED,PermitStatus.PROJECT_CLOSED).contains(p.status);
  case SENIOR_DEPARTMENT_OFFICER->Set.of(PermitStatus.PENDING_FINAL_DECISION,PermitStatus.APPROVED,PermitStatus.REJECTED,PermitStatus.PAYMENT_PENDING,PermitStatus.PERMIT_ISSUED,PermitStatus.INSPECTION_SCHEDULED,PermitStatus.INSPECTION_FAILED,PermitStatus.INSPECTION_PASSED,PermitStatus.PROJECT_CLOSED).contains(p.status)||(p.status==PermitStatus.CORRECTION_REQUIRED&&corrections.findByApplicationIdOrderByRequestedAt(p.id).stream().anyMatch(c->c.requestingRole==Role.SENIOR_DEPARTMENT_OFFICER));
  case ADMIN,DEPARTMENT_OFFICER->true;
 };}
 private PermitRecord lockedAccessible(Long id,AppUser actor){PermitRecord p=lock(id);if(!canAccess(p,actor))throw notFound("Application not found.");return p;}
 private PermitRecord lock(Long id){return permits.lockById(id).orElseThrow(()->notFound("Application not found."));}
 private void own(PermitRecord p,AppUser actor){requireRole(actor,Role.APPLICANT);if(!p.applicantId.equals(actor.id))throw forbidden();}
 private void assigned(Long app,AssignmentType type,AppUser actor){if(active(app,type).map(a->a.assigneeId.equals(actor.id)).orElse(false))return;throw forbidden();}
 private Optional<ApplicationAssignment> active(Long app,AssignmentType type){return assignments.findFirstByApplicationIdAndAssignmentTypeAndActiveTrue(app,type);}
 private void transition(PermitRecord p,PermitStatus next,String action,String note,AppUser actor){PermitStatus old=p.status;p.status=next;p.updatedAt=clock.instant();log(p,old,action,note,actor);}
 private void log(PermitRecord p,PermitStatus old,String action,String note,AppUser actor){history.save(new WorkflowHistory(p,old,action,note,actor,clock.instant()));}
 private void requireRole(AppUser u,Role role){if(u.role!=role)throw forbidden();}
 private static String clean(String s){return s==null?null:s.trim();}private static String required(String s,String message){if(s==null||s.isBlank())throw bad(message);return s.trim();}
 private static void conflict(String m){throw new ResponseStatusException(HttpStatus.CONFLICT,m);}private static ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private static ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}private static ResponseStatusException forbidden(){return new ResponseStatusException(HttpStatus.FORBIDDEN,"You are not authorized to perform this action.");}

 private PermitDtos.ApplicationSummary summary(PermitRecord p){
  String applicantName=person(p.applicantId).name();
  List<String> assignedOfficerNames=assignments.findByApplicationIdOrderByAssignedAt(p.id).stream().filter(a->a.active).map(a->person(a.assigneeId).name()).toList();
  return new PermitDtos.ApplicationSummary(p.id,p.permitNumber,p.projectTitle,p.permitType,applicantName,assignedOfficerNames,p.status,p.reviewRound,p.updatedAt);
 }
 private PermitDtos.Person person(Long id){if(id==null)return null;return users.findById(id).map(u->new PermitDtos.Person(u.id,u.fullName,u.email)).orElse(new PermitDtos.Person(id,"Former user","unavailable"));}
 private PermitDtos.ApplicationView view(PermitRecord p,AppUser actor){
  List<PermitDtos.AssignmentView> av=assignments.findByApplicationIdOrderByAssignedAt(p.id).stream().map(a->new PermitDtos.AssignmentView(a.id,a.assignmentType,person(a.assigneeId),person(a.assignedBy),a.assignedAt,a.active)).toList();
  List<PermitDtos.ReviewView> rv=reviews.findByApplicationIdOrderByReviewDate(p.id).stream().map(r->new PermitDtos.ReviewView(r.id,r.reviewType,person(r.reviewerId),r.recommendation,r.remarks,r.reviewDate,r.reviewRound)).toList();
  List<PermitDtos.CorrectionView> cv=corrections.findByApplicationIdOrderByRequestedAt(p.id).stream().map(c->new PermitDtos.CorrectionView(c.id,person(c.requestedBy),c.requestingRole,c.remarks,c.requestedAt,c.resolved,c.applicantResponse,c.resubmittedAt,c.reviewRound)).toList();
  PermitDtos.PaymentView pay=payments.findByApplicationId(p.id).map(x->new PermitDtos.PaymentView(x.feeAmount,x.paymentStatus,x.paymentReference,person(x.recordedBy),x.recordedAt)).orElse(null);
  List<PermitDtos.InspectionView> iv=inspections.findByApplicationIdOrderByCreatedAt(p.id).stream().map(i->new PermitDtos.InspectionView(i.id,person(i.inspectorId),i.inspectionType,i.scheduledDate,i.conductedDate,i.observations,i.result,i.finalInspection,i.createdAt)).toList();
  List<PermitDtos.HistoryView> hv=history.findByApplicationIdOrderByOccurredAt(p.id).stream().map(h->new PermitDtos.HistoryView(h.id,h.previousStatus,h.newStatus,h.action,h.remarks,h.actorId,h.actorName,h.actorEmail,h.actorRole,h.occurredAt)).toList();
  return new PermitDtos.ApplicationView(p.id,p.permitNumber,person(p.applicantId),p.projectTitle,p.permitType,p.propertyAddress,p.constructionDescription,p.propertyOwnerName,p.contractorArchitectName,p.estimatedProjectCost,p.proposedStartDate,p.supportingDocuments,p.status,p.reviewRound,p.createdAt,p.updatedAt,av,rv,cv,pay,iv,hv,actions(p,actor));
 }
 private Set<String> actions(PermitRecord p,AppUser u){Set<String>a=new LinkedHashSet<>();switch(u.role){case APPLICANT->{if(p.applicantId.equals(u.id)&&(p.status==PermitStatus.DRAFT||p.status==PermitStatus.CORRECTION_REQUIRED))a.add("EDIT");if(p.status==PermitStatus.DRAFT)a.add("SUBMIT");if(p.status==PermitStatus.CORRECTION_REQUIRED)a.add("RESUBMIT");}case DEPARTMENT_OFFICER->{if(p.status==PermitStatus.SUBMITTED||p.status==PermitStatus.RESUBMITTED)a.add("VERIFY_DOCUMENTS");if(Set.of(PermitStatus.DOCUMENT_VERIFICATION,PermitStatus.ASSIGNED,PermitStatus.RESUBMITTED).contains(p.status))a.add("ASSIGN_REVIEWERS");if(Set.of(PermitStatus.APPROVED,PermitStatus.PAYMENT_PENDING,PermitStatus.PERMIT_ISSUED,PermitStatus.INSPECTION_FAILED,PermitStatus.INSPECTION_PASSED).contains(p.status))a.add("ASSIGN_INSPECTOR");}case PERMIT_REVIEWER->{if((p.status==PermitStatus.TECHNICAL_REVIEW||p.status==PermitStatus.RESUBMITTED)&&canAccess(p,u))a.add("TECHNICAL_REVIEW");}case ZONING_OFFICER->{if(p.status==PermitStatus.ZONING_REVIEW&&canAccess(p,u))a.add("ZONING_REVIEW");}case SENIOR_DEPARTMENT_OFFICER->{if(p.status==PermitStatus.PENDING_FINAL_DECISION)a.add("FINAL_DECISION");}case FINANCE_OFFICER->{if(p.status==PermitStatus.APPROVED||p.status==PermitStatus.PAYMENT_PENDING)a.add("RECORD_PAYMENT");}case BUILDING_INSPECTOR->{if(canAccess(p,u)&&Set.of(PermitStatus.PERMIT_ISSUED,PermitStatus.INSPECTION_FAILED,PermitStatus.INSPECTION_PASSED).contains(p.status))a.add("SCHEDULE_INSPECTION");if(canAccess(p,u)&&p.status==PermitStatus.INSPECTION_SCHEDULED)a.add("RECORD_INSPECTION");if(canAccess(p,u)&&p.status==PermitStatus.INSPECTION_PASSED&&inspections.findByApplicationIdOrderByCreatedAt(p.id).stream().anyMatch(i->i.finalInspection&&i.result==InspectionResult.PASSED))a.add("CLOSE_PROJECT");}default->{}}return a;}
}
